window.futvizVista("mapa-tiros","<div class=\"rx-mount\" data-rx=\"tiros\" data-rx-id=\"mapa-tiros\" style=\"min-height:520px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"mapa-tiros\"]={\"id\":\"mapa-tiros\",\"titulo\":\"Mapa de calor de los tiros\",\"bajada\":\"Cada celda es el % de los tiros que sali\u00f3 de ah\u00ed, no un conteo: oscuro es una parte grande del total.\",\"pregunta\":\"\u00bfDesde d\u00f3nde se tira en las 5 ligas?\",\"tabla\":\"tiros\",\"fuente\":\"Understat\",\"enCurso\":{\"2026-27\":9},\"queMirar\":\"De d\u00f3nde se tira en las 5 ligas.\\n- El mapa mira hacia la porter\u00eda: la l\u00ednea de fondo es el borde de arriba y los rect\u00e1ngulos, las \u00e1reas grande y chica.\\n- El color reparte el 100% de los tiros que ves entre celdas de 2\u00d72 m: oscuro es una parte grande del total, no \u00abmuchos tiros\u00bb.\\n- Con \u00abVer\u00bb cada punto es un remate de un jugador o equipo: lleno si fue gol, m\u00e1s grande cuanto m\u00e1s val\u00eda la ocasi\u00f3n.\"};</script>");